import { describe, expect, it } from 'vitest';
import { localLink } from './localLink';
import { initTRPC } from '@trpc/server';
import { createTRPCClient } from '../createTRPCClient';

describe('localLink', () => {
  it('should be able to run a query', async () => {
    const t = initTRPC.create();
    const router = t.router({
      hello: t.procedure.query(() => 'world'),
    });

    const client = createTRPCClient<typeof router>({
      links: [
        localLink({
          router,
        }),
      ],
    });

    const res = await client.hello.query();
    expect(res).toBe('world');
  });
});

import type {
  AnyRouter,
  CreateContextCallback,
  inferRouterContext,
  MaybePromise,
} from '@trpc/server';
import { callTRPCProcedure } from '@trpc/server';
import { observable } from '@trpc/server/observable';
import { getTransformer } from '../internals/transformer';
import type { TransformerOptions } from '../internals/transformer';
import { TRPCClientError } from '../TRPCClientError';
import type { Operation, TRPCLink } from './types';

/**
 * @public
 */
export type LocalLinkOptions<TRouter extends AnyRouter> = {
  router: TRouter;
} & CreateContextCallback<
  inferRouterContext<TRouter>,
  (opts: { op: Operation }) => MaybePromise<inferRouterContext<TRouter>>
> &
  TransformerOptions<TRouter['_def']['_config']['$types']>;

/**
 * @see https://trpc.io/docs/v11/client/links/localLink
 * @public
 */
export function localLink<TRouter extends AnyRouter>(
  opts: LocalLinkOptions<TRouter>,
): TRPCLink<TRouter> {
  const _transformer = getTransformer(opts.transformer);
  return () =>
    ({ op }) =>
      observable((observer) => {
        const { type, path, input, signal } = op;

        const promise = (async () => {
          try {
            const ctx = opts.createContext
              ? await (opts as any).createContext({ op })
              : undefined;

            const result = await callTRPCProcedure({
              router: opts.router,
              path,
              type,
              input,
              ctx,
              signal,
              getRawInput: async () => input,
            });

            if (type === 'subscription') {
              // TODO: Handle subscriptions in next facet
              observer.error(
                TRPCClientError.from(
                  new Error('Subscriptions are not yet implemented in localLink'),
                ),
              );
              return;
            }

            observer.next({
              result: {
                data: result,
              },
            });
            observer.complete();
          } catch (cause) {
            observer.error(TRPCClientError.from(cause));
          }
        })();

        return () => {
          // noop
        };
      });
}

